import { useMemo } from "react";
import { Package } from "lucide-react";
import { getItemPresentation, isPrismaticItem } from "@/lib/itemPresentation";

const SIZES = {
  xs: "h-7 w-7",
  sm: "h-9 w-9",
  md: "h-12 w-12",
  lg: "h-16 w-16",
};

// Static catalog thumbnail for list surfaces. Deliberately cheap: single
// <img>, no 3D stack, no shine animation (the interactive hero keeps those).
// Falls back to a neutral icon when an item has no artwork.
export default function ItemSprite({ item, itemKey, size = "sm", className = "", imgClassName = "" }) {
  const image = useMemo(() => {
    const target = item || (itemKey ? { key: itemKey } : null);
    if (!target) return null;
    try {
      return getItemPresentation(target)?.image || null;
    } catch {
      return null;
    }
  }, [item, itemKey]);
  const prismatic = useMemo(
    () => isPrismaticItem(item || (itemKey ? { key: itemKey } : null)),
    [item, itemKey],
  );

  const box = `${SIZES[size] || SIZES.sm} ${className}`.trim();
  if (!image) {
    return (
      <span
        aria-hidden="true"
        className={`grid shrink-0 place-items-center rounded-md bg-white/[0.04] ${box}`}
      >
        <Package className="h-1/2 w-1/2 text-zinc-600" />
      </span>
    );
  }
  return (
    <span aria-hidden="true" className={`relative grid shrink-0 place-items-center overflow-hidden rounded-md bg-white/[0.03] ${box}`}>
      <img
        src={image.src}
        alt=""
        aria-hidden="true"
        draggable="false"
        loading="lazy"
        decoding="async"
        className={`h-[88%] w-[88%] object-contain ${image.pixelated ? "[image-rendering:pixelated]" : ""} ${prismatic ? "animate-prismatic" : ""} ${imgClassName}`}
      />
    </span>
  );
}
